export const API_BASE_URL='https://x8ki-letl-twmt.n7.xano.io/api:X8-e2j1w/priglosi';
export const DEFAULT_INVITATION_ID=1;
export const BISHKEK_TIME_ZONE='Asia/Bishkek';
export function sanitizeText(value,maxLength=600){return String(value??'').replace(/<[^>]*>/g,' ').replace(/[<>]/g,'').replace(/\s+/g,' ').trim().slice(0,maxLength)}
export function resolveInvitationId(pathname,defaultId=1){const part=String(pathname||'').split('/').filter(Boolean)[0];if(!part)return defaultId;const id=Number(part);return Number.isSafeInteger(id)&&id>0?id:defaultId}
export function withBishkekOffset(value){const text=String(value||'');return /([zZ]|[+-]\d{2}:?\d{2})$/.test(text)?text:`${text}+06:00`}
const pick=(object,language,defaultLanguage='ru')=>object?.[language]||object?.[defaultLanguage]||object?.ru||Object.values(object||{})[0]||{};
function normalizeGuest(g={}){return{name:sanitizeText(g.name,120)||'Гость',wish:sanitizeText(g.wish,600),guestsCount:Math.max(1,Number(g.guests_count)||1),isAttending:g.is_attending===true}}
export function normalizeInvitation(raw={},fallbackId=1){
 const id=Number(raw.id??raw.priglosi_id)||fallbackId,names=raw.names||{},enabled=[...new Set((raw.languages?.enabled||['ru']).filter(x=>['ru','ky','kk'].includes(x)))];if(!enabled.length)enabled.push('ru');const defaultLanguage=enabled.includes(raw.languages?.default)?raw.languages.default:enabled[0];
 const ceremonies=[...(raw.ceremonies||[])].sort((a,b)=>(Number(a.sort_order)||0)-(Number(b.sort_order)||0)).map(item=>{const title={},text={};for(const lang of ['ru','ky','kk']){const c=pick(item.content,lang,defaultLanguage);title[lang]=sanitizeText(c.title,160);text[lang]=sanitizeText(c.text,500)}return{time:sanitizeText(item.time,12),title,text}});
 const venue={content:{},map:{enabled:raw.venue?.map?.enabled===true,googleUrl:String(raw.venue?.map?.google_url||''),twoGisUrl:String(raw.venue?.map?.two_gis_url||'')}};for(const lang of ['ru','ky','kk']){const v=pick(raw.venue?.content,lang,defaultLanguage);venue.content[lang]={type:sanitizeText(v.type,120),name:sanitizeText(v.name,160),address:sanitizeText(v.address,300)}}
 const invitation={},wish={};for(const lang of ['ru','ky','kk']){invitation[lang]=pick(raw.invitation,lang,defaultLanguage);wish[lang]=pick(raw.wish_block?.content,lang,defaultLanguage)}
 return{id,names:{groom:sanitizeText(names.groom??names.has,100),bride:sanitizeText(names.bride??names.wife,100)},dateISO:withBishkekOffset(raw.date),ceremonies,venue,invitation,wishBlock:{enabled:raw.wish_block?.enabled===true,content:wish},music:raw.music||{enabled:false},rsvp:{enabled:raw.rsvp?.enabled!==false,allowGuestWish:raw.rsvp?.allow_guest_wish!==false,maxGuests:Math.max(1,Number(raw.rsvp?.max_guests)||10)},languages:{enabled,default:defaultLanguage},guests:Array.isArray(raw.guests)?raw.guests.map(normalizeGuest):[],raw};
}
function validMapUrl(value){try{const url=new URL(String(value||''));return['http:','https:'].includes(url.protocol)?url.href:''}catch{return''}}
export function buildMapLinks(venue={},language='ru',defaultLanguage='ru'){const data=venue.content?.[language]||venue.content?.[defaultLanguage]||venue.content?.ru||{},query=[data.name,data.address].filter(Boolean).join(', '),google=validMapUrl(venue.map?.googleUrl)||(query?`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`:''),twoGis=validMapUrl(venue.map?.twoGisUrl)||(query?`https://2gis.kg/search/${encodeURIComponent(query)}`:'');return{enabled:Boolean(google||twoGis),google,twoGis}}
export function createGuestPayload(g={}){const attending=g.isAttending===true||g.is_attending===true;return{name:sanitizeText(g.name,120),wish:sanitizeText(g.wish,600),guests_count:attending?Math.max(1,Number(g.guestsCount??g.guests_count)||1):0,is_attending:attending}}
export function buildPatchPayload(raw={},guest={},fallbackId=1){const id=Number(raw.id??raw.priglosi_id)||fallbackId;return{...raw,id,guests:[...(Array.isArray(raw.guests)?raw.guests:[]),createGuestPayload(guest)]}}
async function readJson(response){const text=await response.text();return text?JSON.parse(text):null}
export async function fetchInvitationRaw(id,{fetchImpl=fetch,signal}={}){const response=await fetchImpl(`${API_BASE_URL}/${Number(id)}`,{headers:{Accept:'application/json'},cache:'no-store',signal});if(!response.ok)throw Error(response.status);return readJson(response)}
export function selectFallbackRaw(content={},id){return content.invitations?.[String(id)]||content.invitation||content}
export async function fetchFallbackRaw(id,{fetchImpl=fetch,url='./content.json'}={}){const response=await fetchImpl(url);if(!response.ok)throw Error(response.status);return selectFallbackRaw(await response.json(),id)}
export async function appendGuestToInvitation(id,guest,{fetchImpl=fetch}={}){const latest=await fetchInvitationRaw(id,{fetchImpl}),payload=buildPatchPayload(latest,guest,id),response=await fetchImpl(`${API_BASE_URL}/${Number(id)}/full`,{method:'PATCH',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw Error(response.status);return{raw:payload,invitation:normalizeInvitation(payload,id),payload}}
